#include <crtdbg.h>
#include <windows.h>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <new>
int attempts=0,denied=0,remaining=-1;
int __cdecl hook(int kind,void*,std::size_t,int block,long,const unsigned char*,int) {
  if(kind==_HOOK_ALLOC && block==_NORMAL_BLOCK) {
    ++attempts;
    if(remaining--==0) {++denied;return FALSE;}
  }
  return TRUE;
}
int main(int argc,char**argv) {
  SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX|SEM_NOOPENFILEERRORBOX);
  for(int report:{_CRT_WARN,_CRT_ERROR,_CRT_ASSERT}) {
    _CrtSetReportMode(report,_CRTDBG_MODE_FILE);_CrtSetReportFile(report,_CRTDBG_FILE_STDERR);
  }
  remaining=argc==2?std::atoi(argv[1]):-1;
  bool caught=false;
  auto previous=_CrtSetAllocHook(hook);
  try {std::ofstream file("stream.txt");file<<0.5<<std::endl;file.close();}
  catch(const std::bad_alloc&){caught=true;}
  _CrtSetAllocHook(previous);
  std::printf("allocations=%d denied=%d caught=%d\n",attempts,denied,caught);
  return 0;
}
